function IconButton({icon:I,label,onClick,...props}:any){return <button className="iconbtn" title={label} aria-label={label} onClick={onClick} {...props}><I size={18}/></button>}
function Badge({children,tone=''}:any){return <span className={'badge '+tone}>{children}</span>}
function Avatar({name,size=32}:any){return <span className="avatar" style={{width:size,height:size,fontSize:size/3}}>{initials(name)}</span>}
function Empty({title='No records yet',text='Create a record to see it here.',action}:any){return <div className="empty"><Layers size={28}/><h3>{title}</h3><p>{text}</p>{action}</div>}
function Spark({values,color='#51d6ac',height=40}:any){let max=Math.max(...values,1),min=Math.min(...values,0),pts=values.map((v:number,i:number)=>`${i*100/(values.length-1)},${height-((v-min)/(max-min||1))*(height-6)-3}`).join(' ');return <svg viewBox={`0 0 100 ${height}`} preserveAspectRatio="none" className="spark" style={{height}}><polyline points={pts} fill="none" stroke={color} strokeWidth="1.8" vectorEffect="non-scaling-stroke"/></svg>}
