function Stats({items}:any){return <div className="stats">{items.map((it:any,i:number)=><div className="stat" key={i}><div className="statlabel">{it.label}<ArrowUpRight size={14}/></div><strong>{it.value}</strong><div className="statbottom"><span className={it.down?'red':'green'}>{it.delta||'Demo dataset'}</span>{it.spark&&<Spark values={it.spark}/>}</div></div>)}</div>}
function Panel({title,subtitle,action,children,className=''}:any){return <section className={'panel '+className}><div className="panelhead"><div><h3>{title}</h3>{subtitle&&<p>{subtitle}</p>}</div>{action}</div>{children}</section>}
function Table({rows,columns,onRow,search=true,actions}:any){let[q,Q]=useState(''),[sort,S]=useState(''),[asc,A]=useState(true),[page,P]=useState(0);let filtered=rows.filter((r:any)=>Object.values(r).some(v=>String(v).toLowerCase().includes(q.toLowerCase())));if(sort)filtered=[...filtered].sort((a:any,b:any)=>(typeof a[sort]==='number'?a[sort]-b[sort]:String(a[sort]).localeCompare(String(b[sort])))*(asc?1:-1));let pages=Math.max(1,Math.ceil(filtered.length/10)),p=Math.min(page,pages-1);return <><div className="tabletools">{search&&<label className="searchbox"><Search size={15}/><input placeholder="Search records…" value={q} onChange={e=>{Q(e.target.value);P(0)}}/></label>}<span className="muted">{filtered.length} records</span>{actions}</div><div className="tablewrap"><table><thead><tr>{columns.map((c:any)=><th key={c.key}><button onClick={()=>{S(c.key);A(sort===c.key?!asc:true)}}>{c.title}{sort===c.key?(asc?' ↑':' ↓'):''}</button></th>)}</tr></thead><tbody>{filtered.slice(p*10,p*10+10).map((r:any)=><tr key={r.id} onClick={()=>onRow?.(r)} className={onRow?'clickable':''}>{columns.map((c:any)=><td key={c.key}>{c.render?c.render(r):String(r[c.key]??'—')}</td>)}</tr>)}</tbody></table>{!filtered.length&&<Empty/>}</div><div className="pagination"><span>{p+1} / {pages}</span><button disabled={p===0} onClick={()=>P(p-1)}>Previous</button><button disabled={p===pages-1} onClick={()=>P(p+1)}>Next</button></div></>}
function Form({title,fields,initial={},onSave}:any){const{close}=useApp();let[v,V]=useState<any>(initial),[error,E]=useState('');return <form onSubmit={e=>{e.preventDefault();for(let f of fields){if(f.required!==false&&(v[f.key]===undefined||String(v[f.key]).trim()===''))return E(f.label+' is required');if(f.type==='number'&&(!Number.isFinite(Number(v[f.key]))||(Number(v[f.key])<(f.min??0)||Number(v[f.key])>(f.max??Infinity))))return E(f.label+' must be a valid number');}onSave(v);close();}}><h2>{title}</h2><div className="formgrid">{fields.map((f:any)=><label key={f.key} className={f.wide?'wide':''}>{f.label}{f.options?<select value={v[f.key]??''} onChange={e=>V({...v,[f.key]:e.target.value})}><option value="">Select…</option>{f.options.map((o:any)=><option key={o.value??o} value={o.value??o}>{o.label??o}</option>)}</select>:f.type==='textarea'?<textarea rows={4} value={v[f.key]??''} onChange={e=>V({...v,[f.key]:e.target.value})}/>:<input type={f.type||'text'} min={f.min??(f.type==='number'?0:undefined)} max={f.max} step="any" value={v[f.key]??''} onChange={e=>V({...v,[f.key]:f.type==='number'?Number(e.target.value):e.target.value})}/>}</label>)}</div>{error&&<p className="red" role="alert">{error}</p>}<div className="modalfoot"><button type="button" onClick={close}>Cancel</button><button className="primary" type="submit">Save record</button></div></form>}
function Confirm({title,body,onConfirm}:any){let{close}=useApp();return <><h2>{title}</h2><p>{body}</p><div className="modalfoot"><button onClick={close}>Cancel</button><button className="danger" onClick={()=>{onConfirm();close()}}>Confirm</button></div></>}
function download(name:string,content:string,type='text/csv'){let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([content],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function csv(rows:any[]){let keys=Object.keys(rows[0]||{}).filter(k=>typeof rows[0][k]!=='object');return [keys.join(','),...rows.map(r=>keys.map(k=>'"'+String(r[k]??'').replace(/"/g,'""')+'"').join(','))].join('\n')}
