async function accountRequest(path:string,body?:any){let token=sessionStorage.getItem('traders-account-token'),r=await fetch('/api/'+path,{method:body?'POST':'GET',headers:{'Content-Type':'application/json',...(token?{Authorization:'Bearer '+token}:{})},...(body?{body:JSON.stringify(body)}:{})});let result=await r.json();if(!r.ok)throw Error(result.error||'Request failed');return result}
function AccountRoot(){let[user,U]=useState<any>(null),[boot,B]=useState(true);useEffect(()=>{if(!sessionStorage.getItem('traders-account-token'))return B(false);accountRequest('me').then(v=>U(v.user)).catch(()=>sessionStorage.removeItem('traders-account-token')).finally(()=>B(false))},[]);async function signOut(){await accountRequest('logout',{}).catch(()=>{});sessionStorage.removeItem('traders-account-token');U(null)}if(boot)return <div className="account-loading">Opening your workspace…</div>;return <App key={user?.id||'visitor'} account={user} onAccount={U} onSignOut={signOut}/>}
function AccountEntry({data,role,onRole,onAccount,onExplore}:any){let[mode,MODE]=useState(()=>{let v=sessionStorage.getItem('traders-auth-mode');sessionStorage.removeItem('traders-auth-mode');return v==='signup'?'signup':'signin'}),[name,N]=useState(''),[email,E]=useState(''),[password,P]=useState(''),[choice,C]=useState(()=>sessionStorage.getItem('traders-checkout-intent')||'free'),[error,ERR]=useState(''),[busy,B]=useState(false);let courses=data.courses.filter((c:any)=>c.status==='Published'),plan=data.plans.find((p:any)=>p.name==='Professional');async function submit(e:any){e.preventDefault();B(true);ERR('');try{let result=await accountRequest(mode==='signup'?'register':'login',{name,email,password});sessionStorage.setItem('traders-account-token',result.token);sessionStorage.setItem('traders-checkout-intent',choice);onAccount(result.user)}catch(e:any){ERR(e.message)}finally{B(false)}}return <div className="account-entry"><section className="account-story"><a className="entry-brand" href="?explore=1"><ChartCandlestick/>TRADERS <b>OS</b></a><span className="black-tag">YOUR OWN LEARNING SPACE</span><h1>Your ambition.<br/>Your progress.<br/><em>Your next chapter.</em></h1><p>One account for your courses, practice, tutor feedback and membership.</p><button onClick={onExplore}>← Back to the academy</button><small>Local prototype. Demo checkout activates access without charging money.</small></section><section className="account-form"><div className="course-chips"><button className={mode==='signin'?'active':''} onClick={()=>MODE('signin')}>Sign in</button><button className={mode==='signup'?'active':''} onClick={()=>MODE('signup')}>Create account</button></div><h1>{mode==='signup'?'Start your learning journey.':'Welcome back.'}</h1><p>{mode==='signup'?'Create a personal student account. Choose access after registration.':'Your saved courses and progress are waiting for you.'}</p><form onSubmit={submit}>{mode==='signup'&&<label>Full name<input required maxLength={100} value={name} onChange={e=>N(e.target.value)} autoComplete="name"/></label>}<label>Email address<input required type="email" value={email} onChange={e=>E(e.target.value)} autoComplete="email"/></label><label>Password<input required type="password" minLength={mode==='signup'?10:1} maxLength={128} value={password} onChange={e=>P(e.target.value)} autoComplete={mode==='signup'?'new-password':'current-password'}/></label>{mode==='signup'&&<><small>At least 10 characters. Passwords are stored as salted hashes.</small><label>Choose your starting point<select value={choice} onChange={e=>C(e.target.value)}><option value="free">Free account — explore first</option>{plan&&<option value={'plan:'+plan.id}>Professional membership — {money(plan.price)} / demo month · all published courses</option>}{courses.map((c:any)=><option key={c.id} value={'course:'+c.id}>{c.title} — {money(c.price)} / demo one-time</option>)}</select></label><p className="notice">Registration is free. You will review and confirm demo access in your dashboard.</p></>}{error&&<p role="alert" className="red">{error}</p>}<button className="primary" disabled={busy}>{busy?'Please wait…':mode==='signup'?'Create my account':'Sign in to my workspace'} <ArrowRight size={17}/></button></form><details className="demo-accounts"><summary>Explore staff and sample student demos</summary><p>These are demonstration accounts, separate from your personal student account.</p>{PORTALS.map((p:any)=><button key={p.key} onClick={()=>{MODE('signin');E(p.email);P('VertexDemo');onRole(p.role)}}>{p.name}</button>)}</details></section></div>}
function MembershipWorkspace(){let{data:d,student,notify,refresh}=useApp(),[choice,C]=useState(()=>sessionStorage.getItem('traders-checkout-intent')||'free'),[busy,B]=useState(false),[error,E]=useState('');let courses=d.courses.filter((c:any)=>c.status==='Published'),plan=d.plans.find((p:any)=>p.name==='Professional'),active=d.subscriptions.find((s:any)=>s.status==='Active'&&s.scope==='catalogue'),picked=choice.startsWith('course:')?courses.find((c:any)=>c.id===choice.slice(7)):plan;async function activate(kind:string,id:string){B(true);E('');try{await accountRequest('checkout',{kind,id});sessionStorage.removeItem('traders-checkout-intent');await refresh();notify(kind==='cancel'?'Membership cancelled. Separate course purchases remain available.':'Demo access activated. Your courses are ready.');C('free')}catch(e:any){E(e.message)}finally{B(false)}}return <><div className="membership-hero"><Badge>YOUR ACCOUNT / {student.name}</Badge><h2>Learn your way.</h2><p>Choose one course, or explore the whole academy with a membership.</p><strong>{active?'Professional membership active':'Free account · individual course access available'}</strong></div><div className="twocol"><Panel title="Choose your access" subtitle="Demo checkout — no payment collected or automatic renewal."><label>Course or membership<select value={choice} onChange={e=>C(e.target.value)}><option value="free">Choose an option</option>{plan&&<option value={'plan:'+plan.id}>Professional · all published courses · {money(plan.price)} / demo month</option>}{courses.map((c:any)=><option key={c.id} value={'course:'+c.id}>{c.title} · {money(c.price)} one-time demo</option>)}</select></label>{choice!=='free'&&picked&&<div className="checkout-summary"><h3>{picked.title||picked.name}</h3><strong>{money(picked.price)}</strong><p>{choice.startsWith('plan:')?'Access to all currently published courses and courses published while this membership is active. Manual demo renewal; cancellation removes membership access immediately.':'Access to this course, saved progress and tutor assessment feedback. This separate course access is retained if you cancel a membership.'}</p><button className="primary" disabled={busy} onClick={()=>activate(choice.split(':')[0],choice.slice(choice.indexOf(':')+1))}>{busy?'Activating…':'Confirm demo checkout'}</button></div>}{error&&<p role="alert" className="red">{error}</p>}</Panel><Panel title="Your membership" subtitle="Manage access without losing your learning history.">{active?<><Badge>Active · demo membership</Badge><h2>{active.plan}</h2><p>{money(active.amount)} / demo month. No recurring charge.</p><button disabled={busy} onClick={()=>activate('cancel',active.id)}>Cancel membership now</button><small>Progress and feedback stay saved. Membership-only lessons become locked.</small></>:<p>No active all-course membership. Choose a course or plan to start learning.</p>}<h3>Your access</h3>{courses.filter((c:any)=>d.grants.some((g:any)=>g.course===c.id&&g.active)).map((c:any)=><p key={c.id}><CheckCircle2 size={14}/> {c.title}</p>)}<h3>Demo receipts</h3>{d.invoices.map((i:any)=><div className="receipt-row" key={i.id}><span>{i.description||courses.find((c:any)=>c.id===i.course)?.title||i.id}<small>{i.date} · {i.status}</small></span><b>{money(i.amount)}</b></div>)}</Panel></div></>}

